const crypto = require('crypto');
// Chữ ký TikTok Shop API 202309 (cần đối chiếu khi có app thật, xem contracts/internal/tiktok_api.md)
function tiktokSign(path, query, bodyStr, secret) {
  const keys = Object.keys(query).filter((k) => k !== 'sign' && k !== 'access_token').sort();
  let s = path + keys.map((k) => k + query[k]).join('');
  if (bodyStr) s += bodyStr;
  return crypto.createHmac('sha256', secret).update(secret + s + secret).digest('hex');
}
// Node Code của n8n không có URLSearchParams: tự ghép query
const toQuery = (q) => Object.keys(q).map((k) => encodeURIComponent(k) + '=' + encodeURIComponent(q[k])).join('&');
const appKey = $env.TIKTOK_APP_KEY || '';
const appSecret = $env.TIKTOK_APP_SECRET || '';
if (!appKey || !appSecret) throw new Error('Thiếu TIKTOK_APP_KEY hoặc TIKTOK_APP_SECRET trong .env');
const API_BASE = ($env.TIKTOK_API_BASE || 'https://open-api.tiktokglobalshop.com').replace(/\/$/, '');
const AUTH_BASE = ($env.TIKTOK_AUTH_BASE || 'https://auth.tiktok-shops.com').replace(/\/$/, '');
const parse = (raw) => { try { return typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { return { code: -1, message: String(raw).slice(0, 300) }; } };
// Hạn token TikTok trả về là thời điểm (Unix giây); phòng khi là số giây còn lại thì đổi ra thời điểm
const toEpoch = (v) => (Number(v) < 1e9 ? Math.floor(Date.now() / 1000) + Number(v) : Number(v));

const req = $('Được gọi tới').first().json;
const tok = $input.first().json;
if (!req.path || !String(req.path).startsWith('/')) throw new Error('path phải bắt đầu bằng / (vd /order/202309/orders)');
if (!tok.access_token) throw new Error('Chưa có token TikTok: chủ shop (M1) cần bấm link ủy quyền app');

const method = String(req.method || 'GET').toUpperCase();
const query = { ...(req.query || {}), app_key: appKey, timestamp: Math.floor(Date.now() / 1000) };
if (req.shop !== false) query.shop_cipher = tok.shop_cipher;
const bodyStr = req.body == null ? '' : JSON.stringify(req.body);
query.sign = tiktokSign(req.path, query, bodyStr, appSecret);

const url = API_BASE + req.path + '?' + toQuery(query);
let res;
try {
  res = await this.helpers.httpRequest({
    method, url, body: bodyStr || undefined, json: false, timeout: 20000,
    returnFullResponse: true, ignoreHttpStatusErrors: true,
    headers: { 'x-tts-access-token': tok.access_token, 'content-type': 'application/json' },
  });
} catch (e) {
  return [{ json: { ok: false, http_status: 0, code: -1, message: 'Không gọi được TikTok: ' + e.message,
                    request_id: null, data: null, auth_error: false } }];
}
const body = parse(res.body) || {};
const ok = res.statusCode >= 200 && res.statusCode < 300 && body.code === 0;
const auth_error = res.statusCode === 401 || /token|credential|authoriz/i.test(String(body.message || ''));
return [{ json: {
  ok, http_status: res.statusCode, code: body.code ?? null, message: body.message ?? null,
  request_id: body.request_id ?? null, data: body.data ?? null, auth_error: !ok && auth_error,
} }];
